package com.campuseventhub;
import java.io.IOException;import java.sql.*;import javax.servlet.ServletException;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;
@WebServlet("/registrationReceipt") public class RegistrationReceiptServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{HttpSession s=r.getSession(false);if(s==null||s.getAttribute("student_id")==null){p.sendRedirect("login.jsp");return;}p.setContentType("text/html;charset=UTF-8");try(Connection c=DBConnection.getConnection();PreparedStatement x=c.prepareStatement("SELECT er.*,s.name,s.email,e.event_name,e.event_date,e.event_time,e.venue,e.category FROM event_registrations er JOIN students s ON er.student_id=s.student_id JOIN events e ON er.event_id=e.event_id WHERE er.registration_id=? AND er.student_id=?")){x.setInt(1,Integer.parseInt(r.getParameter("registration_id")));x.setInt(2,(Integer)s.getAttribute("student_id"));ResultSet z=x.executeQuery();if(z.next()){p.getWriter().println("<!DOCTYPE html><html><head><title>Registration Receipt</title><style>body{font-family:Arial;background:#eee;padding:30px}.receipt{max-width:650px;margin:auto;background:white;padding:35px;border:2px solid #2c3e50}.center{text-align:center}.row{padding:9px;border-bottom:1px solid #ddd}.print{padding:10px 18px;background:#007bff;color:white;border:0;border-radius:5px;margin-top:20px}@media print{.print,.back{display:none}}</style></head><body><div class='receipt'><div class='center'><h1>Campus Event Hub</h1><h2>Registration Confirmation</h2><p>Registration ID: <b>REG-"+z.getInt("registration_id")+"</b></p></div><div class='row'><b>Student:</b> "+z.getString("name")+"</div><div class='row'><b>Email:</b> "+z.getString("email")+"</div><div class='row'><b>Event:</b> "+z.getString("event_name")+"</div><div class='row'><b>Date:</b> "+z.getDate("event_date")+"</div><div class='row'><b>Time:</b> "+z.getTime("event_time")+"</div><div class='row'><b>Venue:</b> "+z.getString("venue")+"</div><div class='row'><b>Category:</b> "+z.getString("category")+"</div><div class='row'><b>Participation:</b> "+z.getString("participation_type")+"</div><div class='row'><b>Status:</b> "+z.getString("status")+"</div><div class='center'><button class='print' onclick='window.print()'>Print Receipt</button> <a class='back' href='myEvents'>Back</a></div></div></body></html>");}else p.getWriter().println("<h2>Receipt not found.</h2>");}catch(Exception e){p.getWriter().println("<h2>Error: "+e.getMessage()+"</h2>");}}}
